+      // the editor-only tweaks (layout, line numbers, font).
+      let tweaks = { layout: "split", lineNumbers: true, font: "plex", fontSize: 13, compactToolbar: false };
       try { const r = localStorage.getItem(LS_TWEAKS); if (r) tweaks = { ...tweaks, ...JSON.parse(r) }; } catch {}
       delete tweaks.theme; // retired (was light|dark|system) — now the shared topbar owns it
       tweaks.lineNumbers = tweaks.lineNumbers !== false; // default on
       if (!TWEAK_OPTS.font.some((o) => o.value === tweaks.font)) tweaks.font = "plex";
       if (!TWEAK_OPTS.fontSize.includes(tweaks.fontSize)) tweaks.fontSize = 13;
